window.kbPageData["views/entry/k-8ab3efd4847d5ca0"] = {"key":"entry/k-8ab3efd4847d5ca0","state":{"route":"entry/k-8ab3efd4847d5ca0"},"node":{"id":"k-8ab3efd4847d5ca0","mode":"k","title":"进出口均价","type":"概念与词义","domain":"统计","reading":"","intro":"","priority":100,"aliases":["进出口均价等于对应的贸易额除以贸易量"],"qs":["江苏 2024 C类 行测#125"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"进出口均价是同一时期同一商品的单位贸易金额。进口均价等于进口额除以进口量，出口均价等于出口额除以出口量。","review":{"definition":"进出口均价是同一时期同一商品的单位贸易金额。进口均价等于进口额除以进口量，出口均价等于出口额除以出口量。","explanation":"第125题所附图片是地区社会经济指标表。用世界银行 WITS 公布的2022年中国酱油（HS 210310）对全球贸易数据复算，进口额为19,039.61千美元，进口量为11,673,800千克，出口额为183,844.69千美元，出口量为186,096,000千克。统一换算为美元和吨后，进口均价约为1,631美元/吨，出口均价约为988美元/吨。以出口均价为基准，进口均价高约65.1%，支持A项的“高50%以上”。题干要求选出不能推出的一项，标准答案为D。","references":[{"source":"web-84e413011158f2ba","location":"HS 210310，页面摘要及表格 World 行","quote":"$19,039.61K and quantity 11,673,800Kg"},{"source":"web-3bd3adce2fc5e6fb","location":"HS 210310，页面摘要及表格 World 行","quote":"$183,844.69K and quantity 186,096,000Kg"}],"evidence":"2022年我国酱油进口均价比出口均价高50%以上","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 C类 行测#125":{"paper":"江苏 2024 C类 行测","n":125,"mod":"资料分析","src":["3f1ec77ae8a18519b57e.pdf",26],"asrc":["02d6b49839583bdaf297.pdf",37],"card":"641dd3c77ac613a22133a99b","links":[{"id":"k-8ab3efd4847d5ca0","role":"解题依据","why":"用对应的金额和数量得到进出口单位价格，供差幅判断。"}]}},"terms":{},"references":{"web-84e413011158f2ba":{"name":"世界银行 WITS（UN Comtrade）｜2022年中国酱油进口","url":"https://wits.worldbank.org/trade/comtrade/en/country/CHN/year/2022/tradeflow/Imports/partner/ALL/product/210310"},"web-3bd3adce2fc5e6fb":{"name":"世界银行 WITS（UN Comtrade）｜2022年中国酱油出口","url":"https://wits.worldbank.org/trade/comtrade/en/country/CHN/year/2022/tradeflow/Exports/partner/ALL/product/210310"}},"topics":[],"units":{"k-8ab3efd4847d5ca0":[["江苏 2024 C类 行测#125"]]}};
